function finish(a) {
  a.loop = a.frames.reduce((s, f) => s + f[0], 0);
  const parts = new Set();
  a.frames.forEach(([, p]) => {
    if (p.eyes || p.gx || p.gy) parts.add("eyes");
    if (p.headDy || p.headDx) parts.add("head");
    if (p.hands) parts.add("hands");
    if (p.legs || p.kick) parts.add("legs");
    if (p.dx || p.dy || p.bodyDy || p.dxF) parts.add("body");
    if (p.flip) parts.add("turn");
    if (p.rot) parts.add("rotate");
    if (p.lie) parts.add("template");
    if (p.fx) parts.add("particles");
    if (p.reveal !== undefined || p.tint || p.rowShift || p.ghost) parts.add("signal");
  });
  a.parts = Array.from(parts);
  return a;
}
ANIMS.forEach(finish);
const A = Object.fromEntries(ANIMS.map((a) => [a.id, a]));
const SEQ = {
  boot: finish({ frames: BOOT_IN }), lieDown: finish({ frames: LIE_DOWN }), getUp: finish({ frames: GET_UP }),
  hardland: finish({ frames: HARD_IMPACT }), splat: finish({ frames: SPLAT_IMPACT }), daze: finish({ frames: DAZE }),
  boing: finish({ frames: BOING }), thud: finish({ frames: THUD }), hero: finish({ frames: HERO }), stuck: finish({ frames: STUCK }),
  pancake: finish({ frames: PANCAKE }), roll: finish({ frames: ROLL }), legsup: finish({ frames: LEGSUP })
};

function poseAt(a, t) {
  let tt = ((t % a.loop) + a.loop) % a.loop;
  for (const [d, p] of a.frames) { if (tt < d) return p; tt -= d; }
  return a.frames[0][1];
}
function draw(ctx, pix, ox, oy, S) {
  for (const [x, y, c] of pix) { ctx.fillStyle = c; ctx.fillRect((ox + x) * S, (oy + y) * S, S, S); }
}

// Authored start/impact/lifePose, with host geometry and soma behavior selection.
// The demo's synthetic energy spending and weighted selector are excluded.
function createLifeMotion(random = Math.random) {
  let SW = 320;
  const pointer = { x: -999, y: -999, inside: false };
  const life = [];
  const safeRange = (pl) => [pl.x0 - OX - 1, pl.x1 - OX - 6];
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const cx = (L) => L.x + OX + 4;
  const AIR = ["held", "fall", "boot", "wallhit", "wallslide"];
  const cursorNear = (L) => pointer.inside && Math.abs(pointer.x - cx(L)) < 60 && Math.abs(pointer.y - (L.y + OY + 3)) < 30;
  function neighbor(L) {
    let best = null, bd = 18;
    life.forEach((o) => {
      if (o === L || AIR.includes(o.state) || o.state === "sleep" || Math.abs(o.y - L.y) > 1) return;
      const d = Math.abs(cx(o) - cx(L));
      if (d < bd) { bd = d; best = o; }
    });
    return best;
  }
  const pickW = (w) => {
    let r = random() * w.reduce((s, x) => s + x[1], 0);
    for (const [s, v] of w) { r -= v; if (r <= 0) return s; }
    return w[0][0];
  };

  function start(L, s) {
    L.state = s; L.t = 0;
    if (s === "idle") L.dur = 1200 + random() * 2600;
    else if (s === "walk" || s === "run") {
      const run = s === "run";
      const dist = run ? 24 + Math.floor(random() * 50) : 8 + Math.floor(random() * 36);
      let dir = random() < 0.5 ? -1 : 1;
      if (L.social > 0.6 && pointer.inside) dir = pointer.x < cx(L) ? -1 : 1;
      L.walkTo = clamp(L.x + dir * dist, 0, SW - FW);
      if (Math.abs(L.walkTo - L.x) < 4) L.walkTo = clamp(L.x - dir * dist, 0, SW - FW);
      if (L.on && random() < 0.6) { const [lo, hi] = safeRange(L.on); L.walkTo = clamp(L.walkTo, lo, hi); }
      if (L.walkTo === L.x) { start(L, "idle"); return; }
      L.flip = L.walkTo < L.x; L.step = 0; L.stepT = 0;
    } else if (s === "lieDown") {
      L.sleepKind = pickW([["nod", 3], ["bubble", 2], ["curl", 3], ["sprawl", 2], ["stand", 1]]);
      if (L.sleepKind === "stand") L.state = "sleep";
    }
    else if (s === "fall") { L.peak = L.y; L.tumbled = false; L.on = null; }
  }

  function impact(L) {
    const d = L.y - L.peak;
    L.x = Math.round(L.x); L.vx = 0; L.vy = 0;
    if (L.tumbled || d >= 26) start(L, pickW([["splat", 3], ["stuck", 2], ["pancake", 2], ["roll", 2], ["legsup", 2], ["boing", 1]]));
    else if (d >= 9) start(L, pickW([["hardland", 3], ["boing", 2], ["thud", 2], ["hero", 0.7]]));
    else start(L, "land");
  }

  const AFTER = {
    lieDown: "sleep", getUp: "stretch", splat: "confused", hardland: "idle", daze: "idle", boot: "look",
    stuck: "confused", pancake: "shiver", roll: "idle", legsup: "idle", boing: "idle", thud: "idle", hero: "idle"
  };
  const NOBLINK = new Set(["sleep", "boot", "lieDown", "getUp", "splat", "wallhit", "wallslide", "stuck", "pancake", "roll", "legsup", "thud"]);
  function lifePose(L) {
    let p;
    switch (L.state) {
      case "boot": p = L.t < 0 ? { reveal: 0 } : poseAt(SEQ.boot, L.t); break;
      case "idle": {
        const watching = L.social > 0.35 && cursorNear(L);
        p = { headDy: Math.floor((L.t + L.i * 300) / 800) % 2 };
        if (watching && pointer.y < L.y + OY - 2) p.gy = -1;
        break;
      }
      case "walk": p = WALK[L.step % WALK.length][1]; break;
      case "run": p = RUN[L.step % RUN.length][1]; break;
      case "sleep": p = poseAt(A["sleep_" + L.sleepKind], L.t); break;
      case "held": p = UP; break;
      case "fall": {
        const d = L.y - L.peak;
        if (L.tumbled) p = merge(TUCK, { rot: TUMBLE_ROT[Math.floor(L.t / 90) % 4] });
        else if (d >= 10) p = FLAIL[Math.floor(L.t / 90) % 4][1];
        else p = UP;
        break;
      }
      case "wallhit": p = merge(UP, { eyes: "closed", fx: [P.wallHit] }); break;
      case "wallslide": p = merge(UP, { eyes: "closed" }); break;
      case "land": p = { headDy: 1 }; break;
      default: p = poseAt(SEQ[L.state] || A[L.state], L.t);
    }
    p = merge(p);
    if (L.blink > 0 && !p.lie && !NOBLINK.has(L.state)) p.eyes = "closed";
    p.flip = L.flip !== !!p.flip;
    return p;
  }


  return { start, impact, pose: lifePose, AFTER,
    configure(width, cursor) { SW = width; Object.assign(pointer, cursor); },
    register(body) { life.push(body); },
  };
}

export { MASK, AN, REPS, ANIMS, A, SEQ, compose, derive, poseAt, FW, FH, OX, OY, createLifeMotion };
